import copy
import random
import pytest

GENS = {}
try:
    from generator.piano_params_stage2 import PianoGeneratorStage2
    GENS["piano"] = PianoGeneratorStage2
except Exception:
    pass
try:
    from generator.guitar_params_stage2 import GuitarGeneratorStage2
    GENS["guitar"] = GuitarGeneratorStage2
except Exception:
    pass
try:
    from generator.strings_params_stage2 import StringsGeneratorStage2
    GENS["strings"] = StringsGeneratorStage2
except Exception:
    pass
try:
    from generator.bass_params_stage2 import BassGeneratorStage2
    GENS["bass"] = BassGeneratorStage2
except Exception:
    pass
try:
    from generator.drums_params_stage2 import DrumsGeneratorStage2
    GENS["drums"] = DrumsGeneratorStage2
except Exception:
    pass

def _require(*roles):
    missing = [r for r in roles if r not in GENS]
    if missing:
        pytest.skip(f"generator(s) missing: {missing}")

def make_section(label="verse", bar=0, beat=0, tempo=120.0, ql_per_bar=4.0, index=1, chordmap=None):
    return {"label": label, "bar": bar, "beat": beat, "tempo": tempo,
            "ql_per_bar": ql_per_bar, "index": index, "chordmap": chordmap or {}}

def make_context(bpm=120.0):
    return {"beat_grid": {"bpm": bpm}}

def run_gen(role, section, mix_ctx, params, seed=1234):
    Gen = GENS[role]
    g = Gen(overrides={"mix_context": mix_ctx}, rnd=random.Random(seed))
    try:
        part = g.apply(section_meta=section, mix_context=mix_ctx, params=params, seed=seed)
    except TypeError:
        part = g.apply(section, mix_ctx, params, seed)
    # 正規化して返す
    if isinstance(part, dict):
        return part
    return {"notes": getattr(part, "notes", []), "controls": getattr(part, "controls", {})}

# ---------------- RH/LH 分割（Phase 28 のメタ） ----------------
def test_piano_export_meta_has_rh_lh_and_name():
    _require("piano")
    section = make_section(label="bridge", tempo=116.0, index=5)
    ctx = make_context(bpm=116.0)
    params = {
        "style": "complex",
        "export": {"quantize_ql": 0.125, "track_split": ["RH","LH"], "name_fmt": "{idx:02d}_{role}_{section}"}
    }
    p = run_gen("piano", section, ctx, params)
    meta = ((p.get("controls") or {}).get("meta") or {})
    assert "export_name" in meta and isinstance(meta["export_name"], str)
    ts = meta.get("track_split")
    assert ts and isinstance(ts, (list, tuple)) and "RH" in ts and "LH" in ts

# ---------------- Controls（Phase 24）整合性 -------------------
def _extract_controls(part):
    c = (part.get("controls") or {})
    rpn = c.get("rpn") or c.get("RPN") or []
    pb = c.get("pb14") or c.get("pitchbend") or c.get("PB") or []
    cc = c.get("cc") or {}
    if isinstance(cc, dict):
        cc11 = cc.get(11) or cc.get("11") or []
    else:
        cc11 = c.get("cc11") or []
        if not cc11 and isinstance(cc, list):
            cc11 = [e for e in cc if str(e.get("cc")) in ("11", 11)]
    return rpn, pb, cc11

@pytest.mark.parametrize("role", ["piano", "guitar", "strings", "bass"])
def test_controls_rpn_pb_cc11_integrity(role):
    _require(role)
    section = make_section(label="chorus", tempo=128.0)
    ctx = make_context(bpm=128.0)
    params = {"style": "moderate", "controls": {"expression_curve": "arch", "bend_range": 2}}
    p = run_gen(role, section, ctx, params)
    rpn, pb, cc11 = _extract_controls(p)

    # RPN：0回または1回。PBがあるなら1回必須。時刻 t >= 0
    assert len(rpn) <= 1
    if pb:
        assert len(rpn) == 1
    if rpn:
        assert float(rpn[0].get("time", 0.0)) >= 0.0

    # PB：14bit 範囲、時系列単調
    for ev in pb:
        val = int(ev.get("value", 0))
        assert -8191 <= val <= 8191
    if pb:
        times = [float(ev.get("time", 0.0)) for ev in pb]
        assert all(t2 >= t1 for t1, t2 in zip(times, times[1:]))

    # CC11：0..127、時系列単調
    for ev in cc11:
        v = int(ev.get("value", 0))
        assert 0 <= v <= 127
    if cc11:
        tcc = [float(ev.get("time", 0.0)) for ev in cc11]
        assert all(t2 >= t1 for t1, t2 in zip(tcc, tcc[1:]))

