# tests/test_export_split_internal_threshold_optional.py

import random
import pytest

GENS = {}
try:
    from generator.piano_params_stage2 import PianoGeneratorStage2
    GENS["piano"] = PianoGeneratorStage2
except Exception:
    pass

def _require(*roles):
    missing = [r for r in roles if r not in GENS]
    if missing:
        pytest.skip(f"generator(s) missing: {missing}")

def make_section(label="verse", tempo=120.0, index=1):
    return {"label": label, "bar": 0, "beat": 0, "tempo": tempo, "ql_per_bar": 4.0, "index": index}

def make_context(bpm=120.0):
    return {"beat_grid": {"bpm": bpm}}

def run_piano(section, mix_ctx, params, seed=2025):
    Gen = GENS["piano"]
    g = Gen(overrides={"mix_context": mix_ctx}, rnd=random.Random(seed))
    try:
        return g.apply(section_meta=section, mix_context=mix_ctx, params=params, seed=seed)
    except TypeError:
        return g.apply(section, mix_ctx, params, seed)

def test_internal_rh_lh_split_if_tagged():
    _require("piano")
    section = make_section(label="verse", tempo=120.0, index=2)
    ctx = make_context(bpm=120.0)
    params = {"style": "complex", "export": {"track_split": ["RH","LH"], "quantize_ql": 0.25}}

    p = run_piano(section, ctx, params)
    if not isinstance(p, dict):
        p = {"notes": getattr(p, "notes", []), "controls": getattr(p, "controls", {})}

    notes = p.get("notes") or []
    # 手がタグ付けされているか？（想定：n['hand'] in {'RH','LH'} など。無ければ skip）
    tagged = [n for n in notes if isinstance(n, dict) and any(k in n for k in ("hand", "lane", "track"))]
    if not tagged:
        pytest.skip("手分けの実タグは未実装（メタのみ）— 現仕様ならOK")

    def which(n):
        if "hand" in n: return n["hand"]
        if "lane" in n: return n["lane"]
        if "track" in n: return n["track"]
        return None

    rh = [n for n in tagged if str(which(n)).upper().startswith("RH")]
    lh = [n for n in tagged if str(which(n)).upper().startswith("LH")]

    # どちらかが完全0なら分割失敗の可能性（実装仕様次第で緩め判定）
    assert len(rh) > 0 and len(lh) > 0

