import random, json
from pathlib import Path

def _fake_mix():
    return {"beat_grid":{"bpm":120.0},"activity":{},"sections":[{"bar":0,"label":"verse","start_ql":0.0}]}

def _fake_secs():
    return [{"label":"verse","bar":0,"beat":0,"tempo":120.0,"ql_per_bar":4.0,"index":1}]

def test_name_tokens_are_resolved(tmp_path, monkeypatch):
    # 直接 Base の postprocess_export を経由するのが本筋だが、
    # ここではスクリプトのフォールバック命名を軽く確認
    mix = tmp_path/"mix.json"; mix.write_text(json.dumps(_fake_mix()), encoding="utf-8")
    secs = tmp_path/"secs.json"; secs.write_text(json.dumps(_fake_secs()), encoding="utf-8")
    outd = tmp_path/"out"
    import subprocess, sys
    cmd = [sys.executable, "ops/stage2_batch_export.py",
           "--mix", str(mix), "--sections", str(secs),
           "--roles", "piano", "--style", "simple",
           "--outdir", str(outd), "--project", "TST",
           "--name-fmt", "{date}_{seq}_{project}_{role}_{section}_{style}",
           "--date-fmt", "%Y0101", "--seq-width", "2"]
    # 存在しないGenerator環境では skip 相当（ここでは returncode 0 でもファイル=0を許容）
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, check=False)
        if r.returncode != 0:
            return  # 実行環境次第で skip
    except Exception:
        return
    # 生成物があれば命名にトークンが解決されている
    mids = list(outd.glob("*.mid"))
    if mids:
        assert any("_piano_verse_simple.mid" in str(p.name) for p in mids)

