 def enforce_min_dwell(events: List[Dict[str,Any]], *, global_min: float = 0.0, per_section: Optional[Dict[str,float]] = None, sections=None):
     if not events: return events
     if (global_min or per_section) is None: return events
     out = []
     def _sec_at(tql: float) -> Optional[str]:
         if not sections: return None
         try:
             return sections.label_at_ql(tql)
         except Exception:
             return None
     min_prev = None
     last = None
     for i,e in enumerate(events):
         t0 = float(e["time"]) ; t1 = float(events[i+1]["time"]) if i+1<len(events) else t0
         sec = _sec_at(t0)
         m = float(global_min or 0.0)
         if per_section and sec in per_section:
             try: m = max(m, float(per_section[sec]))
             except Exception: pass
         if (t1 - t0) < m:
             # 短すぎ：隣接とマージ（同root優先）
             if i+1 < len(events):
                 # 次と同rootなら吸収
                 if events[i+1]["root"] == e["root"]:
                     continue
             if out and out[-1]["root"] == e["root"]:
                 # 前と同rootなら延長不要、スキップ
                 continue
         out.append(e)
     return out
