# セクション設定ロード
section_cfg = _load_decoration_config(args.dec_config) if args.decorate else None

# キー・バイアス
key_bias = None
if args.dec_key_bias:
    name, mode = args.dec_key_bias.split(":")
    name = name.strip(); mode = mode.strip().lower()
    tonic = _NAME_TO_PC.get(name.upper(), 0)
    key_bias = (tonic, "maj" if mode.startswith("maj") else "min")

if args.decorate:
    get_section = (lambda ql: labeler(ql) if callable(labeler) else None)

    events = decorate_events_with_bar_chroma_v3(
        events, C_bars, label_at_ql=get_section, ql_per_bar=args.ql_per_bar,
        tau_on=args.dec_tau_on, tau_off=args.dec_tau_off,
        sus_tau_on=args.dec_sus_tau_on, sus_tau_off=args.dec_sus_tau_off,
        switch_margin=args.dec_switch_margin, min_dwell_bars=args.dec_min_dwell_bars,
        triad_guard=args.dec_triad_guard,
        density_window_bars=args.dec_density_window_bars,
        max_decorations_per_window=args.dec_density_max,
        priority=args.decorate_priority, allow_sus=(not args.dec_no_sus),
        allow_m6=args.dec_allow_m6,
        key_bias=key_bias, key_bias_penalty=args.dec_key_bias_penalty,
        section_cfg=section_cfg,
    )

