      delta_scores.sort(reverse=True)
      keep_indices = {0, len(pruned) - 1}  # intro/outro固定
      keep_indices.update([idx for _, idx in delta_scores[:max_sections - 2]])
      pruned = [pruned[i] for i in sorted(keep_indices)]

