# =========================
# Song-specific Presets 🎛️
# =========================

# 各プリセットは「推奨モード／プロファイル／ゲイン」に加えて、
# 非ダイアトニックの“青音”などを軽く押し出す optional パラメータを持てます。
# extra_pc_offsets: ルートからの半音オフセット（例：b3=+3, #11/b5=+6）
# extra_boost: その相対ブースト（root値×extra_boost を下限に持ち上げ）

_PRESETS = {
    "lydian_shimmer": {
        "mode": "lydian",
        "profile": "airy",
        "char_gain": 1.12,
        "avoid_gain": 1.00,
        # Lydianは #11(=+6) と 9th(=+2) をより空間的に
        "extra_pc_offsets": [2, 6],
        "extra_boost": 0.60
    },
    "dorian_soul": {
        "mode": "dorian",
        "profile": "melodic",
        "char_gain": 1.08,
        "avoid_gain": 1.00,
        # Dorianは Nat6(=+9) と 9th(=+2) を少し前へ
        "extra_pc_offsets": [2, 9],
        "extra_boost": 0.55
    },
    "mixolydian_blues": {
        "mode": "mixolydian",
        "profile": "chordal",
        "char_gain": 1.10,
        "avoid_gain": 0.95,   # avoid弱め＝“濁り”の余地を残す
        # Blue notes: b3(=+3), #11/b5(=+6) を控えめに許容
        "extra_pc_offsets": [3, 6],
        "extra_boost": 0.52
    },
    "phrygian_spice": {
        "mode": "phrygian",
        "profile": "cinematic",
        "char_gain": 1.00,
        "avoid_gain": 1.15,   # 不安定域の濁り抑制
        # b2(=+1) を軸に、b6(=+8) を副次的に
        "extra_pc_offsets": [1, 8],
        "extra_boost": 0.50
    },
    "aeolian_cinematic": {
        "mode": "aeolian",
        "profile": "dark_minor",
        "char_gain": 1.08,
        "avoid_gain": 1.10,
        # b6(=+8), b7(=+10) と 9th(=+2) を映画的に
        "extra_pc_offsets": [8, 10, 2],
        "extra_boost": 0.55
    },
    "ionian_vintage": {
        "mode": "ionian",
        "profile": "chordal",
        "char_gain": 1.00,
        "avoid_gain": 0.95,
        # 6th(=+9) と 9th(=+2) をほんのり（ジャズ/シティポップの気配）
        "extra_pc_offsets": [2, 9],
        "extra_boost": 0.50
    },
    "locrian_ambient": {
        "mode": "locrian",
        "profile": "airy",
        "char_gain": 0.95,    # ロクリアンは特色を少し柔らげる
        "avoid_gain": 1.10,
        # b5(=+6) を中心に、b2(=+1) を薄く
        "extra_pc_offsets": [6, 1],
        "extra_boost": 0.48
    }
}

def list_presets() -> list[str]:
    """登録済みプリセット名を返す。"""
    return sorted(_PRESETS.keys())

def describe_preset(name: str) -> dict:
    """プリセットの内容を取得（UI/ログ用）。存在しない場合は {}。"""
    p = _PRESETS.get(name.lower())
    return dict(p) if p else {}

def _apply_extra_boosts(mask: list[float], root_pc: int,
                        offsets: list[int], level: float, normalize: bool) -> list[float]:
    if not offsets or level <= 0.0:
        return mask
    # ルートの値を基準に、指定PCを「最低でも root*level」まで引き上げる
    root_val = mask[root_pc]
    floor_val = root_val * level
    for off in offsets:
        pc = (root_pc + int(off)) % 12
        if mask[pc] < floor_val:
            mask[pc] = floor_val
    if normalize:
        s = sum(mask)
        if s > 1e-12:
            mask = [x / s for x in mask]
    return mask

def mask_for_preset(key: str, preset_name: str, *,
                    normalize: bool = True) -> list[float]:
    """
    例:
      mask_for_preset('D', 'lydian_shimmer')
      mask_for_preset('Fm', 'dorian_soul')
    """
    p = _PRESETS.get(preset_name.lower())
    if not p:
        # 不明プリセット→通常解決（NO-OP的フォールバック）
        return mask_for_key(key, scheme="balanced", normalize=normalize)

    mode   = p["mode"]
    scheme = p["profile"]
    cg     = p.get("char_gain", 1.0)
    ag     = p.get("avoid_gain", 1.0)

    base = mask_for_key_mode(key, mode, scheme=scheme, normalize=True,
                             char_gain=cg, avoid_gain=ag)

    # 追加ブースト（blue notesなど）
    root_pc, canon_mode = _parse_key_mode_text(key, mode)
    extra = p.get("extra_pc_offsets", [])
    level = float(p.get("extra_boost", 0.0))
    return _apply_extra_boosts(list(base), root_pc, extra, level, normalize)

# （任意）セクション辞書からの解決ヘルパ
def resolve_mask_from_section(section: dict, default_key: str) -> list[float] | None:
    """
    section: {"key_hint":"D", "mode":"lydian", "preset":"lydian_shimmer", ...}
    key_hint/mode/preset の優先順で解決。情報が無ければ None（NO-OP）を返す。
    """
    key = section.get("key_hint") or default_key
    if not key:
        return None
    if "preset" in section:
        return mask_for_preset(key, section["preset"])
    if "mode" in section:
        return mask_for_key_mode(key, section["mode"])
    # mode 指定が無い場合は Ionian/Aeolian 推定
    return mask_for_key(key)


