# DrumGeneratorStage2 — wrapper example
# Added by Sona 音楽家 — 2025-10-21 13:02:32 JST
from __future__ import annotations
from instrument_stage2_base import InstrumentStage2Base
try:
    import drum_generator as v1
except Exception:
    v1 = None

class DrumGeneratorStage2(InstrumentStage2Base):
    def build_notes(self, section, chords, tempo_map=None, **kw):
        notes = []
        if v1 is not None:
            for fn_name in ("generate_drums", "generate", "render", "compose"):
                gen = getattr(v1, fn_name, None)
                if callable(gen):
                    try:
                        notes = gen(chords=chords, section=section, params=self.params)
                        break
                    except TypeError:
                        try:
                            notes = gen(chords, section)
                            break
                        except Exception:
                            continue
                    except Exception:
                        continue
        try:
            notes = self.apply_ai_filters(notes, section=section)
        except Exception:
            pass
        try:
            notes = self.humanize(notes, profile=self.params.get("humanize_profile", "drums"))
        except Exception:
            pass
        try:
            notes = self.quantize_to_tempo_map(notes, tempo_map)
        except Exception:
            pass
        return notes


