total_loops_pop909 = 0

for role in [('bass', 'bass'), ('chords', 'piano'), ('melody', 'piano')]:
    role_name, inst_name = role
    role_path = pop909_base / role_name
    data_file = role_path / f"{inst_name}_00000.pkl"
    
    if data_file.exists():
        with open(data_file, 'rb') as f:
            data = pickle.load(f)
            if isinstance(data, list):
                count = len(data)
            elif isinstance(data, dict):
                count = len(data.get('loops', []))
            else:
                count = 0
            
            size = data_file.stat().st_size / 1024
            total_loops_pop909 += count
            
            print(f"\n{role_name.upper():<8} ({inst_name}) → {count:>6,} patterns ({size:>6.1f} KB)")
            
            # サンプルデータ確認
            if isinstance(data, list) and data:
                sample = data[0]
                if isinstance(sample, dict):
                    keys = list(sample.keys())[:8]
                    print(f"         Keys: {', '.join(keys)}")
                    if 'notes' in sample:
                        print(f"         Notes: {len(sample['notes'])} events")

print(f"\n{'-'*65}")
print(f"POP909 合計: {total_loops_pop909:,} patterns (~1.3 MB)")

