# auto_sections_from_energy_extended を直接実行（デバッグ版）
def _safe_round_extended(x: float, n: int = 3) -> float:
    try:
        return round(float(x), n)
    except:
        return 0.0

def auto_sections_from_energy_extended_debug(midi_data, downbeats_ql, min_bars=8):
    """デバッグ版: エラーメッセージを出力"""
    out = {"energy": [], "sections": []}
    try:
        nb = len(downbeats_ql)
        print(f"DEBUG: nb={nb}, downbeats_ql={downbeats_ql[:5]}...")
        
        if nb < 1:
            print("DEBUG: nb < 1, returning early")
            return out
        
        # downbeats_ql を秒に変換
        tpq = 480
        tempo_changes = midi_data.get_tempo_changes()
        print(f"DEBUG: tempo_changes={tempo_changes}")
        
        if len(tempo_changes[0]) > 0:
            base_tempo = float(tempo_changes[1][0])
        else:
            base_tempo = 120.0
        print(f"DEBUG: base_tempo={base_tempo}")
        
        # QL → 秒
        db_sec = []
        for ql in downbeats_ql:
            sec_val = (60.0 / base_tempo) * (ql / tpq)
            db_sec.append(sec_val)
        
        # 末尾番兵
        if db_sec:
            db_sec.append(db_sec[-1] + 4.0)
        
        print(f"DEBUG: db_sec[0:5]={db_sec[:5]}")
        print(f"DEBUG: len(db_sec)={len(db_sec)}")
        
        # 実ノート数カウント
        if not db_sec or len(db_sec) < 2:
            print("DEBUG: db_sec invalid, using fallback")
            bar_energy = [0.2] * nb
        else:
            bar_energy = [0] * nb
            note_count = 0
            for ins in midi_data.instruments:
                for n in ins.notes:
                    note_count += 1
                    for i in range(nb):
                        if db_sec[i] <= n.start < db_sec[i + 1]:
                            bar_energy[i] += 1
                            break
            print(f"DEBUG: note_count={note_count}, bar_energy[0:5]={bar_energy[:5]}")
        
        # 正規化
        m = max(bar_energy) if nb > 0 else 1
        m = m if m > 0 else 1.0
        print(f"DEBUG: max(bar_energy)={m}")
        
        out["energy"] = [[i, _safe_round_extended(bar_energy[i] / m, 3)] for i in range(nb)]
        print(f"DEBUG: len(out['energy'])={len(out['energy'])}")
        
        # 分割
        cuts = [0]
        step = max(min_bars, max(1, nb // 3))
        print(f"DEBUG: step={step}")
        
        b = step
        while b < nb:
            cuts.append(b)
            b += step
        if cuts[-1] != nb:
            cuts.append(nb)
        
        print(f"DEBUG: cuts={cuts}")
        
        labels = ["intro", "verse", "chorus", "outro"]
        for j, bar_idx in enumerate(cuts[:-1]):
            label = labels[min(j, len(labels) - 1)]
            out["sections"].append({"bar": int(bar_idx), "label": label})
        
        print(f"DEBUG: len(out['sections'])={len(out['sections'])}")
        
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()
    
    return out

# downbeatsを抽出
downbeats = midi_data.get_downbeats()
downbeats_ql = [int(db * 480) for db in downbeats]
print(f"downbeats_ql (first 5): {downbeats_ql[:5]}")
print(f"Total downbeats: {len(downbeats_ql)}")

# 実行
result = auto_sections_from_energy_extended_debug(midi_data, downbeats_ql)
print(f"\nResult:")
print(f"  energy entries: {len(result['energy'])}")
print(f"  sections: {len(result['sections'])}")
if result['sections']:
    print(f"  section labels: {[s['label'] for s in result['sections']]}")
