import json, tempfile
from pathlib import Path
from scripts.lamda_v2.compat.lamda_stage2_extractor_shim import main as shim_main

def test_shim_runs(tmp_path: Path, monkeypatch):
    # 準備：簡単なMIDIをfixturesに置いてある想定 or 事前に生成
    midi = Path("tests/fixtures/midi/smoke.mid")
    outd = tmp_path / "out"
    argv = [
        "prog",
        "--input-dir", str(midi),
        "--output-dir", str(outd),
        "--emit-csv", "aggregate",
        "--print-summary",
    ]
    monkeypatch.setattr("sys.argv", argv)
    shim_main()
    js = next(outd.glob("*.stage2.json"))
