# scripts/fix_timesig_in_json.py
from __future__ import annotations
import argparse, json
from pathlib import Path

def maybe_fix(js: dict, tol=0.65, min_bars=16) -> bool:
    tm = [s for _,s in js.get("timesig_map_time",[])]
    if not tm or not all(s=="1/4" for s in tm): return False
    db = js.get("downbeats_ql",[])
    if len(db)<min_bars+1: return False
    bars = [db[i+1]-db[i] for i in range(len(db)-1)]
    avg = sum(bars)/max(1,len(bars))
    if abs(avg-4.0)>tol: return False
    js["timesig_map"] = [(b,"4/4") for b,_ in js.get("timesig_map",[])]
    js["timesig_map_time"] = [(t,"4/4") for t,_ in js.get("timesig_map_time",[])]
    return True

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("json_dir")
    args = ap.parse_args()
    fixed=0
    for p in Path(args.json_dir).glob("*.stage2.json"):
        js = json.loads(p.read_text())
        if maybe_fix(js):
            p.write_text(json.dumps(js, ensure_ascii=False))
            fixed+=1
    print(f"✅ fixed {fixed} files")
if __name__=="__main__":
    main()

